[
    {"title":"销售费用总额","value":"2016年为2,270.50万元，2017年为2,557.76万元，2018年为2,861.37万元，2019年1-6月为1,248.69万元。","evidence":"报告期各期，公司销售费用总额呈现上涨趋势，分别为 2,270.50 万元、2,557.76 万元、2,861.37 万元和 1,248.69 万元。","type":"table_fact"},
    {"title":"销售费用率","value":"2016年为28.54%，2017年为17.18%，2018年为14.44%，2019年1-6月为25.45%。","evidence":"销售费用占营业收入比重呈现下降趋势，分别为 28.54%、17.18% 和 14.44%。销售费用率 25.45%。","type":"table_fact"},
    {"title":"职工薪酬","value":"2016年为1,599.29万元，2017年为1,721.48万元，2018年为1,906.98万元，2019年1-6月为765.55万元。","evidence":"报告期各期，公司销售费用中职工薪酬金额分别为 1,599.29 万元、1,721.48 万元、1,906.98 万元和 765.55 万元。","type":"table_fact"},
    {"title":"销售费用增长情况","value":"2017年较2016年增加287.26万元，增长12.65%；2018年较2017年增加303.62万元，增长11.87%。","evidence":"2017 年销售费用较 2016 年增加 287.26 万元，增加 12.65%；2018 年销售费用较 2017 年增加 303.62 万元，增加 11.87%。","type":"table_fact"}
]

